class Solution:

	def subarrayCount(self, arr, N, k):
		count = self.AtMostk(arr, k) - self.AtMostk(arr, k - 1)
		return count

	def AtMostk(self, arr, k):
		count = 0
		i = 0
		j = 0
		a = {}
		while j < len(arr):
			a[arr[j]] = a.get(arr[j], 0) + 1
			while len(a) > k:
				a[arr[i]] -= 1
				if a[arr[i]] == 0:
					del a[arr[i]]
				i += 1
			count += j - i + 1
			j += 1
		return count
